record.field:
website = env.ref('guest_house.website_industry')
to_deactivate = [ 'website_sale.carousel_product_indicators_left', 'website_sale.product_comment', 'website.footer_custom', 'website.header_search_box', 'website.header_text_element', 'website.header_visibility_standard', 'website.homepage', 'website.contactus', ] # website.header_call_to_action is active in core, and views/website_templates.xml # ships the website-specific views for option_footer_scrolltop and # template_footer_descriptive already active. Activating those keys here is a # no-op at best: ir.ui.view.write() with a website_id redirects onto the # website-specific view that shares the key, so the generic never flips. to_activate = [ 'website_sale.carousel_product_indicators_bottom', 'website_sale.tax_indication', ]
ctx = {'website_id': website.id}
for xml_id in to_deactivate: env.ref(xml_id).with_context(**ctx).write({'active': False}) for xml_id in to_activate: env.ref(xml_id).with_context(**ctx).write({'active': True})
menus = env['website.menu'] base_domain = [('website_id', '=', website.id)]
# Default menu items to remove: /appointment is copied from the generic menu # tree (website_appointment) onto every new website, /contactus is reachable # through the header "Contact Us" call to action instead. menus.search(base_domain + [('url', 'in', ['/appointment', '/contactus'])]).unlink() # Default menus to rename/reorder menus.search(base_domain + [('url', '=', '/')], limit=1).write({'name': 'Home', 'sequence': 10}) menus.search(base_domain + [('url', '=', '/shop')], limit=1).write({'name': 'Book', 'sequence': 20}) # Add About menu item top_menu = menus.search(base_domain + [('parent_id', '=', False)], limit=1) if not menus.search(base_domain + [('url', '=', '/about')]): menus.create({ 'name': 'About', 'url': '/about', 'website_id': website.id, 'parent_id': top_menu.id if top_menu else False, 'sequence': 55, })
